import { siteConfig } from '../data/siteConfig.js';
import { sectionLabel, placeholder } from './shared.js';
export function Introduction() { return `<section id="about" class="section introduction container" aria-labelledby="intro-title">${sectionLabel('02','INTRODUCTION')}<div class="intro-grid"><div><h2 id="intro-title" class="reveal">A little <br>about <span class="soft-text">me.</span></h2><div class="intro-image reveal"><img src="/assets/images/earth-horizon-mobile.webp" alt="Earth’s thin blue horizon, photographed from orbit by NASA" width="1100" height="618" loading="lazy"><span>A DIFFERENT PERSPECTIVE.</span><span class="image-cross">+</span></div></div><div class="intro-copy"><span class="eyebrow reveal">SOMEWHERE BETWEEN CURIOSITY & CREATION</span><h3 class="reveal">${siteConfig.introduction.headline.replace('\n','<br>')}</h3><p class="placeholder-copy reveal">${siteConfig.introduction.note}</p><div class="reveal">${placeholder('BIOGRAPHY · PLACEHOLDER')}</div><ul class="identity-list">${siteConfig.introduction.roles.map((s,i)=>`<li class="reveal"><span class="muted">0${i+1}</span>${s}<span class="identity-plus">+</span></li>`).join('')}</ul><p class="small-note reveal">以上身份与地域均为可编辑占位内容。</p></div></div></section>`; }
